begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_function('public','reverse_payment',array['uuid','uuid','text','date','uuid'],'Verified receipts have an audited reversal command');

create function pg_temp.rid(n integer) returns uuid language sql immutable as $$select ('cb000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email) values(pg_temp.rid(1),'reversal-owner@example.invalid');
insert into public.organizations(id,name,slug) values(pg_temp.rid(10),'Reversal tests','reversal-tests');
insert into public.memberships(org_id,user_id,role) values(pg_temp.rid(10),pg_temp.rid(1),'owner');
insert into public.clients(id,org_id,name) values(pg_temp.rid(20),pg_temp.rid(10),'Buyer');
insert into public.invoices(id,org_id,client_id,number) values(pg_temp.rid(30),pg_temp.rid(10),pg_temp.rid(20),'DRAFT-R');
insert into public.invoice_items(org_id,invoice_id,description,unit_price_satang) values(pg_temp.rid(10),pg_temp.rid(30),'Service',10000);
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.rid(1))::text,true);
set local role authenticated;
select public.update_business_profile(pg_temp.rid(10),'Seller','Address',null,'not_registered');
select public.issue_invoice(pg_temp.rid(10),pg_temp.rid(30),(select version from public.invoices where id=pg_temp.rid(30)),pg_temp.rid(49));
select public.submit_internal_payment_claim(pg_temp.rid(10),pg_temp.rid(30),10000,'Reported receipt',pg_temp.rid(50));
select public.review_payment_claim_with_evidence(pg_temp.rid(10),(select id from public.payment_claims where org_id=pg_temp.rid(10)),10000,'Bank statement',pg_temp.rid(51),'verified',current_date,'cheque');
select public.update_finance_lock_date(pg_temp.rid(10),current_date);
select throws_ok($$select public.reverse_payment(pg_temp.rid(10),(select id from public.payments where org_id=pg_temp.rid(10) and amount_satang>0),'Bounced cheque',current_date,pg_temp.rid(52))$$,'P0001','Finance period is locked','Reversal respects posting lock');
select public.update_finance_lock_date(pg_temp.rid(10),null);
select lives_ok($$select public.reverse_payment(pg_temp.rid(10),(select id from public.payments where org_id=pg_temp.rid(10) and amount_satang>0),'Bounced cheque',current_date,pg_temp.rid(52))$$,'Verified cheque reverses');
select is((select sum(amount_satang)::bigint from public.payments where org_id=pg_temp.rid(10) and verification_state='verified'),0::bigint,'Sum verified cash is net settled cash');
select is((select status::text from public.invoices where id=pg_temp.rid(30)),'sent','Reversal reopens invoice');
select is((select sum(amount_satang)::bigint from public.payment_allocations where org_id=pg_temp.rid(10)),0::bigint,'Reversal offsets allocation');
select is((select count(*) from public.payments where org_id=pg_temp.rid(10) and amount_satang>0 and verification_state='verified'),1::bigint,'Original receipt is retained and verified');
select lives_ok($$select public.reverse_payment(pg_temp.rid(10),(select id from public.payments where org_id=pg_temp.rid(10) and amount_satang>0),'Bounced cheque',current_date,pg_temp.rid(52))$$,'Reversal retry recovers same offset');
select throws_ok($$select public.reverse_payment(pg_temp.rid(10),(select id from public.payments where org_id=pg_temp.rid(10) and amount_satang>0),'Wrong posting',current_date,pg_temp.rid(53))$$,'P0001','Unreversed verified receipt required','Second command cannot reverse same cash twice');
select is((select count(*) from public.audit_log where org_id=pg_temp.rid(10) and action='payment_reversed'),1::bigint,'Reversal has exactly one audit entry');
select * from finish();
rollback;
